/**
 * @description Tests for the guided setup (IntegrationHubSetup, IntegrationHubSetupSchema, IntegrationHubSetupOptions):
 * admin and reader reads, field paths with parents, class pickers without test classes, save of new and changed
 * records, readable save errors, and save refused to non-admins.
 */
@IsTest
private class IntegrationHubSetupTest {

    @TestSetup
    static void setup() {
        IntegrationHubTestData.setupAll();
    }

    /**
     * @description A payload class inside this test class: it must never be offered.
     */
    public class StubPayload implements IntegrationHub.IPayloadBuilder {
        /**
         * @description Builds nothing.
         * @param request the send
         * @return no bodies
         */
        public Map<Id, Object> build(IntegrationHub.PayloadRequest request) {
            return new Map<Id, Object>();
        }
    }

    private static IntegrationHubSetup.FieldInfo fieldNamed(List<IntegrationHubSetup.FieldInfo> fields, String apiName) {
        for (IntegrationHubSetup.FieldInfo f : fields) {
            if (f.apiName == apiName) {
                return f;
            }
        }
        return null;
    }

    private static String errorOf(String objectName, Map<String, Object> values) {
        try {
            IntegrationHubSetup.save(objectName, JSON.serialize(values));
        } catch (AuraHandledException e) {
            return e.getMessage();
        }
        return null;
    }

    /* ApexClass built in memory (Body is read-only on the sObject), for isTest. */
    private static ApexClass apexClass(String name, String body) {
        return (ApexClass) JSON.deserialize(JSON.serialize(new Map<String, Object>{
            'attributes' => new Map<String, Object>{ 'type' => 'ApexClass' }, 'Name' => name, 'Body' => body }), ApexClass.class);
    }

    private static Boolean refusedPicker(Integer which) {
        try {
            switch on which {
                when 0 {
                    IntegrationHubSetup.fieldOptions('IH_Event__c');
                }
                when 1 {
                    IntegrationHubSetup.objectOptions();
                }
                when 2 {
                    IntegrationHubSetup.namedCredentials();
                }
                when 3 {
                    IntegrationHubSetup.userAccess(UserInfo.getUserId());
                }
                when else {
                    IntegrationHubSetup.classOptions('response');
                }
            }
        } catch (AuraHandledException e) {
            return e.getMessage() == 'Integration Hub Admin permission is required.';
        }
        return false;
    }

    @IsTest
    static void adminReadsAnEventWithItsHelp() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Event__c ev = IntegrationHubTestData.eventByKey(IntegrationHubTestData.OUT_KEY);
            IntegrationHubSetup.Setup s = IntegrationHubSetup.getSetup('IH_Event__c', ev.Id);
            Assert.isTrue(s.isAdmin, 'the admin may edit');
            Assert.areEqual('IH_Event__c', s.objectApiName, 'the object');
            Assert.areEqual(IntegrationHubTestData.OUT_KEY, s.values.get('Event_Key__c'), 'the values are read');
            Assert.areEqual('Test system', s.names.get('Connection__c'), 'the connection is named');
            Assert.areEqual('IH_Test', s.credential, 'the connection Named Credential is given');
            IntegrationHubSetup.FieldInfo path = fieldNamed(s.fields, 'Path__c');
            Assert.isTrue(String.isNotBlank(path.help), 'the help text is given');
            IntegrationHubSetup.FieldInfo direction = fieldNamed(s.fields, 'Direction__c');
            Assert.areEqual('Outbound', direction.defaultValue, 'the picklist default');
            Assert.areEqual(2, direction.options.size(), 'Outbound and Inbound');
            Assert.isTrue(fieldNamed(s.fields, 'Event_Key__c').required, 'Event Key is required');
            Assert.areEqual('sfTransactionId', fieldNamed(s.fields, 'Transaction_Id_Key__c').defaultValue, 'the quotes are removed');
            Assert.isFalse(s.credentialExists, 'IH_Test is not a Named Credential of the test org');
            Assert.areEqual('IH_Connection__c', s.relatedObject.value, 'the Related Object API name');
            Assert.areEqual(Schema.SObjectType.IH_Connection__c.getLabel(), s.relatedObject.label, 'the Related Object label');
            Assert.areEqual('API name IH_Connection__c · Id prefix ' + Schema.SObjectType.IH_Connection__c.getKeyPrefix(),
                s.relatedObject.detail, 'the API name and Id prefix');
        }
    }

    @IsTest
    static void adminReadsAConnectionWithItsEvents() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            Id connId = IntegrationHubTestData.eventByKey(IntegrationHubTestData.OUT_KEY).Connection__c;
            IntegrationHubSetup.Setup s = IntegrationHubSetup.getSetup(null, connId);
            Assert.areEqual('IH_Connection__c', s.objectApiName, 'the object comes from the Id');
            Assert.areEqual(3, s.eventCount, 'the events on the connection');
            Assert.areEqual(1, s.inboundCount, 'one inbound event');
            Assert.areEqual(3, s.events.size(), 'the events are listed');
            Assert.areEqual('Integration Hub Admin', s.userAccess, 'the inbound user is the admin');
            Assert.isNotNull(s.names.get('Inbound_User__c'), 'the inbound user is named');
            Assert.isFalse(s.credentialExists, 'IH_Test is not a Named Credential of the test org');
            Assert.areEqual(IntegrationHubTestData.CALLBACK_KEY, s.events[0].eventKey, 'the events are listed by key (ACC_CB first)');
            Assert.areEqual('Outbound', s.events[0].direction, 'with their direction');
            Assert.isTrue(s.events[0].active, 'and their active flag');
            Assert.isNull(s.relatedObject, 'a connection has no Related Object');
            IntegrationHubSetup.Setup fresh = IntegrationHubSetup.getSetup('IH_Connection__c', null);
            Assert.isTrue(fresh.values.isEmpty(), 'a new record has no values');
            Assert.areEqual('60', fieldNamed(fresh.fields, 'Timeout_Seconds__c').defaultValue, 'the number default');
        }
    }

    @IsTest
    static void readerWithoutAccessIsRefused() {
        Id eventId = IntegrationHubTestData.eventByKey(IntegrationHubTestData.OUT_KEY).Id;
        System.runAs(IntegrationHubTestData.reader()) {
            IntegrationHubSetup.Setup fresh = IntegrationHubSetup.getSetup('IH_Event__c', null);
            Assert.isFalse(fresh.isAdmin, 'a reader may not edit');
            String error;
            try {
                IntegrationHubSetup.getSetup('IH_Event__c', eventId);
            } catch (AuraHandledException e) {
                error = e.getMessage();
            }
            Assert.areEqual('You cannot open this record.', error, 'the reader cannot see the event');
            String wrongObject;
            try {
                IntegrationHubSetup.getSetup('Account', null);
            } catch (AuraHandledException e) {
                wrongObject = e.getMessage();
            }
            Assert.isTrue(wrongObject.contains('Only Integration'), 'other objects are refused');
        }
    }

    @IsTest
    static void nonAdminCannotSaveOrPick() {
        System.runAs(IntegrationHubTestData.reader()) {
            String error = errorOf('IH_Event__c', new Map<String, Object>{ 'Name' => 'X', 'Event_Key__c' => 'X_KEY' });
            Assert.areEqual('Integration Hub Admin permission is required.', error, 'save is for admins');
            String pickError;
            try {
                IntegrationHubSetup.classOptions('payload');
            } catch (AuraHandledException e) {
                pickError = e.getMessage();
            }
            Assert.areEqual('Integration Hub Admin permission is required.', pickError, 'pickers are for admins');
            Integer refused = 0;
            for (Integer i = 0; i < 5; i++) {
                refused += refusedPicker(i) ? 1 : 0;
            }
            Assert.areEqual(5, refused, 'every picker is for admins');
            Assert.areEqual(0, [SELECT COUNT() FROM IH_Event__c WHERE Event_Key__c = 'X_KEY' WITH SYSTEM_MODE], 'nothing was saved');
        }
    }

    @IsTest
    static void classOptionsLeaveOutTestClasses() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            for (String kind : new List<String>{ 'payload', 'response', 'inbound' }) {
                for (IntegrationHubSetup.Option o : IntegrationHubSetup.classOptions(kind)) {
                    Assert.isFalse(o.value.startsWithIgnoreCase('IntegrationHubSetupTest'), 'this test class is not offered: ' + o.value);
                    Assert.isFalse(o.value.startsWithIgnoreCase('IntegrationHubTestData'), 'test data stubs are not offered: ' + o.value);
                }
            }
            Assert.isTrue(IntegrationHubSetupOptions.isTest(apexClass('T', '@isTest private class T {}')),
                'a body with @IsTest is a test');
            Assert.isFalse(IntegrationHubSetupOptions.isTest(apexClass('H', '(hidden)')), 'a hidden body is not a test');
            Assert.isFalse(IntegrationHubSetupOptions.isTest(apexClass('D', '/** Not a test: see the @IsTest class. */\npublic class D {} // @IsTest elsewhere')),
                'a mention of @IsTest in a comment is not a test');
            Assert.isFalse(IntegrationHubSetupOptions.isTest(apexClass('N', null)), 'no body is not a test');
            Set<String> offered = new Set<String>();
            for (IntegrationHubSetup.Option o : IntegrationHubSetup.classOptions('payload')) {
                offered.add(o.value.toLowerCase());
            }
            Assert.isFalse(offered.contains('integrationhubsetuptest.stubpayload'), 'IntegrationHubSetupTest is not offered');
            String unknown;
            try {
                IntegrationHubSetup.classOptions('other');
            } catch (AuraHandledException e) {
                unknown = e.getMessage();
            }
            Assert.isTrue(unknown.startsWith('Unknown class kind'), 'only the three kinds');
        }
    }

    @IsTest
    static void fieldOptionsIncludeParentPaths() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            Set<String> paths = new Set<String>();
            Boolean parentNamed = false;
            for (IntegrationHubSetup.FieldOption o : IntegrationHubSetup.fieldOptions('IH_Event__c')) {
                paths.add(o.value);
                parentNamed = parentNamed || (o.value == 'Connection__r.Name' && o.parent == 'Connection__r');
            }
            Assert.isTrue(paths.contains('Event_Key__c'), 'a field of the object');
            Assert.isTrue(paths.contains('Connection__r.Name'), 'a parent field one lookup up');
            Assert.isTrue(parentNamed, 'the parent field names its relationship');
            Assert.isNull(IntegrationHubPayloadPaths.invalid('IH_Event__c', new List<String>{ 'Connection__r.Name', 'Event_Key__c' }),
                'the framework accepts the offered paths');
            String error;
            try {
                IntegrationHubSetup.fieldOptions('No_Such_Object__c');
            } catch (AuraHandledException e) {
                error = e.getMessage();
            }
            Assert.isTrue(error.startsWith('Unknown object'), 'an unknown object is explained');
            Assert.isNotNull(IntegrationHubSetup.objectOptions(), 'the object list is answered');
            for (IntegrationHubSetup.Option o : IntegrationHubSetup.objectOptions()) {
                Assert.isTrue(o.detail.startsWith('API name ' + o.value), 'each object shows its API name: ' + o.detail);
            }
            Assert.isNull(IntegrationHubSetupRecord.objectSummary('No_Such_Object__c'), 'an unknown object has no summary');
            Assert.areEqual('API name X__c', IntegrationHubSetupRecord.objectDetail('X__c', null), 'no prefix, no prefix text');
            Assert.isNotNull(IntegrationHubSetup.namedCredentials(), 'the Named Credentials are listed');
            Assert.areEqual('Integration Hub Admin', IntegrationHubSetup.userAccess(IntegrationHubTestData.admin().Id), 'admin access');
            Assert.isNull(IntegrationHubSetup.userAccess(null), 'no user, no access');
        }
    }

    @IsTest
    static void fieldOptionsWorkForAnyObject() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            Map<String, IntegrationHubSetup.FieldOption> byPath = new Map<String, IntegrationHubSetup.FieldOption>();
            for (IntegrationHubSetup.FieldOption o : IntegrationHubSetup.fieldOptions('IH_Connection__c')) {
                byPath.put(o.value, o);
            }
            Assert.isTrue(byPath.containsKey('Named_Credential__c'), 'a field of IH_Connection__c');
            Assert.isNull(byPath.get('Named_Credential__c').parent, 'a field of the object has no parent');
            Assert.isTrue(byPath.containsKey('Inbound_User__r.Name'), 'a parent field through the user lookup');
            Assert.areEqual('Inbound_User__r', byPath.get('Inbound_User__r.Name').parent, 'the parent relationship');
            Assert.isNotNull(byPath.get('Inbound_User__r.Name').parentLabel, 'the parent label');
            Assert.isTrue(byPath.containsKey('Owner.Name'), 'a polymorphic owner offers Name');
            Assert.isNull(IntegrationHubPayloadPaths.invalid('IH_Connection__c',
                new List<String>{ 'Named_Credential__c', 'Inbound_User__r.Name', 'Owner.Name' }), 'the framework accepts the offered paths');
        }
    }

    @IsTest
    static void saveCreatesAnInactiveEventAndUpdatesIt() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            Id connId = IntegrationHubTestData.eventByKey(IntegrationHubTestData.OUT_KEY).Connection__c;
            Id newId = IntegrationHubSetup.save('IH_Event__c', JSON.serialize(new Map<String, Object>{
                'Name' => 'New event', 'Event_Key__c' => 'NEW_EVENT', 'Direction__c' => 'Outbound', 'Active__c' => true,
                'Connection__c' => connId, 'Related_Object__c' => 'IH_Connection__c', 'Retention_Days__c' => '30',
                'Payload_Fields__c' => 'Name, Owner.Name', 'Expects_Callback__c' => 'false'
            }));
            IH_Event__c saved = [SELECT Active__c, Retention_Days__c, Payload_Fields__c, Connection__c, Transaction_Id_Key__c,
                Share_With_Related_Record__c FROM IH_Event__c WHERE Id = :newId WITH SYSTEM_MODE];
            Assert.isFalse(saved.Active__c, 'a new event is saved inactive');
            Assert.areEqual('sfTransactionId', saved.Transaction_Id_Key__c, 'the field defaults apply to a new record');
            Assert.isTrue(saved.Share_With_Related_Record__c, 'the checkbox default applies');
            Assert.areEqual(30, saved.Retention_Days__c.intValue(), 'the number is converted');
            Assert.areEqual(connId, saved.Connection__c, 'the lookup is set');
            IntegrationHubSetup.save('IH_Event__c', JSON.serialize(new Map<String, Object>{
                'Id' => newId, 'Path__c' => '/api/v1/new', 'Active__c' => true }));
            saved = [SELECT Active__c, Path__c FROM IH_Event__c WHERE Id = :newId WITH SYSTEM_MODE];
            Assert.isTrue(saved.Active__c, 'an edit may switch it on');
            Assert.areEqual('/api/v1/new', saved.Path__c, 'the edit is saved');
        }
    }

    @IsTest
    static void saveErrorsAreReadable() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            String rule = errorOf('IH_Event__c', new Map<String, Object>{ 'Name' => 'Bad', 'Event_Key__c' => 'BAD_CLASS',
                'Payload_Source__c' => 'Apex Class' });
            Assert.isTrue(rule.contains('Enter the Payload Class'), 'the validation rule message: ' + rule);
            String duplicate = errorOf('IH_Event__c', new Map<String, Object>{ 'Name' => 'Dup',
                'Event_Key__c' => IntegrationHubTestData.OUT_KEY });
            Assert.isTrue(duplicate.contains('Event_Key__c'), 'the field is named: ' + duplicate);
            String notAllowed = errorOf('IH_Event__c', new Map<String, Object>{ 'Name' => 'X', 'OwnerId' => UserInfo.getUserId() });
            Assert.isTrue(notAllowed.startsWith('This field cannot be set here'), 'only setup fields: ' + notAllowed);
            String notNumber = errorOf('IH_Connection__c', new Map<String, Object>{ 'Name' => 'C', 'Timeout_Seconds__c' => 'ten' });
            Assert.isTrue(notNumber.contains('enter a number'), 'a number is checked: ' + notNumber);
            String wrongType = errorOf('IH_Connection__c', new Map<String, Object>{
                'Id' => IntegrationHubTestData.eventByKey(IntegrationHubTestData.OUT_KEY).Id, 'Name' => 'C' });
            Assert.isTrue(wrongType.startsWith('The record is not'), 'the Id must match the object: ' + wrongType);
            Assert.areEqual('Nothing to save.', errorOf('IH_Connection__c', null), 'no values');
            Id connId = IntegrationHubSetup.save('IH_Connection__c', JSON.serialize(new Map<String, Object>{
                'Name' => 'New system', 'Named_Credential__c' => 'Other_API', 'Timeout_Seconds__c' => 30,
                'Headers__c' => '{"x-api-version":"2"}' }));
            Assert.isFalse([SELECT Active__c FROM IH_Connection__c WHERE Id = :connId WITH SYSTEM_MODE].Active__c,
                'a new connection is saved inactive');
        }
    }
}
